<?php
 namespace Pterodactyl\Http\Requests\Api\Client\Servers\Addons; use Pterodactyl\Models\Server; use Pterodactyl\Models\Permission; use Pterodactyl\Contracts\Http\ClientPermissionsRequest; use Pterodactyl\Http\Requests\Api\Client\ClientApiRequest; class DatabaseImportRequest extends ClientApiRequest implements ClientPermissionsRequest { public function permission(): string { return Permission::ACTION_DATABASE_VIEW_PASSWORD; } public function authorize(): bool { if (!parent::authorize()) { return false; } $server = $this->route()->parameter('server'); return $server instanceof Server && $this->user()->can(Permission::ACTION_DATABASE_UPDATE, $server); } } 